import sqlite3; con=sqlite3.connect('file:data/guidebook.db?mode=ro',uri=True)
print('user_version',con.execute('pragma user_version').fetchone())
ts=[t for (t,) in con.execute("select name from sqlite_master where type='table' and name not like 'sqlite_%' order by name")]
vs=con.execute("select count(*) from sqlite_master where type='view'").fetchone()[0]
empty=[];rows={}
for t in ts:
  n=con.execute(f'select count(*) from "{t}"').fetchone()[0]; rows[t]=n
  if n==0: empty.append(t)
print('tables',len(ts),'views',vs,'empty',len(empty))
for t in sorted(rows,key=lambda x:-rows[x]): 
  if rows[t]: print(rows[t],t)
print('EMPTY:',' '.join(empty))
